2	
3	// A declared check IS its messages — the format carries no comments, no
4	// description and no doc pointer (#827), so what/fix/failureMessage are the
5	// whole teaching surface. That only works when each field stays one readable
6	// clause: the evidence, the one action, the one consequence. This meta-check
7	// keeps the spec files honest the way eslint-plugin-eslint-plugin lints
8	// ESLint's own rules — word caps per message field, and no fix string
9	// hand-repeated across one rule's assertions (the rule-level `fix` default
10	// exists precisely so a shared remedy is written once).
11	const DECLARED = /(^|\/)declared-checks\.json$/;
12	const MAX_WORDS = 32;
13	const MESSAGE_KEYS = new Set(['what', 'fix', 'failureMessage']);
14	
15	const words = (s) => s.trim().split(/\s+/).filter(Boolean).length;
16	
17	// Every message-field string in one spec, with its key and whether it sits at
18	// the rule level (a rule-level fix is the dedup mechanism, never a duplicate).
19	function messageFields(node, atRuleLevel, out) {
20	  if (Array.isArray(node)) {
21	    for (const v of node) messageFields(v, false, out);
22	    return;
23	  }
24	  if (node === null || typeof node !== 'object') return;
25	  for (const [key, value] of Object.entries(node)) {
26	    if (MESSAGE_KEYS.has(key) && typeof value === 'string') {
27	      out.push({ key, value, atRuleLevel });
28	    } else {
29	      messageFields(value, false, out);
30	    }
31	  }
32	}
33	
34	const rule = {
35	  id: 'declared-check-messages',
36	  severity: 'blocking',
37	  description: 'Every declared check\'s message fields stay within the word caps, with no fix repeated inside one rule',
38	  why: 'a declaration has no comments or doc pointer — its messages are the whole check, and a message that runs to a paragraph (or a remedy pasted per assertion) stops being readable as one',
39	
40	  run(ctx) {
41	    const out = [];
42	    for (const file of ctx.files.filter((f) => DECLARED.test(f))) {
43	      const text = ctx.read(file);
44	      if (text === null) continue;
45	      let specs;
46	      try { specs = JSON.parse(text); } catch { continue; } // unparsable is the loader's finding
47	      if (!Array.isArray(specs)) continue;
48	      for (const spec of specs) {
49	        if (!spec || typeof spec !== 'object' || typeof spec.id !== 'string') continue;
50	        const anchor = text.slice(0, text.indexOf(`"${spec.id}"`)).split('\n').length;
51	        const fields = [];
52	        messageFields(spec, true, fields);
53	        for (const f of fields) {
54	          const n = words(f.value);
55	          if (n > MAX_WORDS) {
56	            out.push(finding(rule, {
57	              file,
58	              line: anchor,
59	              what: `"${spec.id}" has a ${f.key} of ${n} words (max ${MAX_WORDS}): "${f.value.slice(0, 60)}…"`,
60	              fix: 'cut the field to its one clause — the evidence in `what`, the single action in `fix`, the single consequence in `failureMessage`',
61	            }));
62	          }
63	        }
64	        const fixes = fields.filter((f) => f.key === 'fix' && !f.atRuleLevel).map((f) => f.value);
65	        const repeated = [...new Set(fixes.filter((v, i) => fixes.indexOf(v) !== i))];
66	        for (const value of repeated) {
67	          out.push(finding(rule, {
68	            file,
69	            line: anchor,
70	            what: `"${spec.id}" repeats one fix verbatim across ${fixes.filter((v) => v === value).length} assertions: "${value.slice(0, 60)}…"`,
71	            fix: 'state the shared remedy once as the rule-level "fix" and drop the per-assertion copies',
72	          }));
73	        }
74	      }
75	    }
76	    return out;
77	  },
